import { test } from 'node:test'
import assert from 'node:assert/strict'
import { NODE_STATE_TRANSITIONS, STAGE_STATE_TRANSITIONS } from './lifecycleTypes.ts'

const nodeTransitions = NODE_STATE_TRANSITIONS as Record<string, readonly string[]>
const stageTransitions = STAGE_STATE_TRANSITIONS as Record<string, readonly string[]>


test('REWORK node state exists and transitions to ENTERING', () => {
  assert.ok('REWORK' in nodeTransitions, 'REWORK should be a key in node transitions')
  const next = nodeTransitions.REWORK
  assert.ok(Array.isArray(next), 'REWORK transitions should be an array')
  assert.ok(next.includes('ENTERING'), 'REWORK should allow ENTERING as a next state')
})


test('rework cycle: COMPLETED -> REWORK -> ENTERING is a valid path', () => {
  const fromCompleted = nodeTransitions.COMPLETED
  assert.ok(fromCompleted.includes('REWORK'), 'COMPLETED should allow REWORK')
  const fromRework = nodeTransitions.REWORK
  assert.ok(Array.isArray(fromRework), 'REWORK state should exist')
  assert.ok(fromRework.includes('ENTERING'), 'REWORK should allow ENTERING')
})


test('existing PENDING -> ENTERING transition is preserved', () => {
  assert.deepEqual([...nodeTransitions.PENDING], ['ENTERING'])
})


test('FAILED node state remains terminal', () => {
  assert.deepEqual([...nodeTransitions.FAILED], [])
})


test('stage COMPLETED remains terminal (stages do not support rework)', () => {
  assert.deepEqual([...stageTransitions.COMPLETED], [])
})
